50     struct D3D12QueryPayload
51     {
52         uint32_t m_queryIdStart = 0;
53         uint32_t m_queryCount = 0;
54     };
55 
56     // Command queue context.
57     class D3D12QueueCtx
58     {
59         friend class D3D12ZoneScope;
60 
61         ID3D12Device* m_device = nullptr;
62         ID3D12CommandQueue* m_queue = nullptr;
63         uint8_t m_contextId = 255;  // TODO: apparently, 255 means "invalid id"; is this documented somewhere?
64         ID3D12QueryHeap* m_queryHeap = nullptr;
65         ID3D12Resource* m_readbackBuffer = nullptr;
66 
67         // In-progress payload.
68         uint32_t m_queryLimit = 0;
69         std::atomic<uint32_t> m_queryCounter = 0;
70         uint32_t m_previousQueryCounter = 0;
71 
72         uint32_t m_activePayload = 0;
73         ID3D12Fence* m_payloadFence = nullptr;
74         std::queue<D3D12QueryPayload> m_payloadQueue;
75 
76         UINT64 m_prevCalibrationTicksCPU = 0;
77 
78         void RecalibrateClocks()
79         {
80             UINT64 cpuTimestamp;
81             UINT64 gpuTimestamp;
82             if (FAILED(m_queue->GetClockCalibration(&gpuTimestamp, &cpuTimestamp)))
83             {
84                 TracyD3D12Panic("failed to obtain queue clock calibration counters.", return);
85             }
86 
87             int64_t cpuDeltaTicks = cpuTimestamp - m_prevCalibrationTicksCPU;
88             if (cpuDeltaTicks > 0)
89             {
90                 static const int64_t nanosecodsPerTick = int64_t(1000000000) / GetFrequencyQpc();
91                 int64_t cpuDeltaNS = cpuDeltaTicks * nanosecodsPerTick;
92                 // Save the device cpu timestamp, not the Tracy profiler timestamp:
93                 m_prevCalibrationTicksCPU = cpuTimestamp;
94 
95                 cpuTimestamp = Profiler::GetTime();
96 
97                 auto* item = Profiler::QueueSerial();
98                 MemWrite(&item->hdr.type, QueueType::GpuCalibration);
99                 MemWrite(&item->gpuCalibration.gpuTime, gpuTimestamp);
100                 MemWrite(&item->gpuCalibration.cpuTime, cpuTimestamp);
101                 MemWrite(&item->gpuCalibration.cpuDelta, cpuDeltaNS);
102                 MemWrite(&item->gpuCalibration.context, GetId());
103                 SubmitQueueItem(item);
104             }
105         }
106 
107         tracy_force_inline void SubmitQueueItem(tracy::QueueItem* item)
108         {
109 #ifdef TRACY_ON_DEMAND
110             GetProfiler().DeferItem(*item);
111 #endif
112             Profiler::QueueSerialFinish();
113         }
114 
115     public:
116         D3D12QueueCtx(ID3D12Device* device, ID3D12CommandQueue* queue)
117             : m_device(device)
118             , m_queue(queue)
119         {
120             // Verify we support timestamp queries on this queue.
121 
122             if (queue->GetDesc().Type == D3D12_COMMAND_LIST_TYPE_COPY)
123             {
124                 D3D12_FEATURE_DATA_D3D12_OPTIONS3 featureData{};
125 
126                 HRESULT hr = device->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS3, &featureData, sizeof(featureData));
127                 if (FAILED(hr) || (featureData.CopyQueueTimestampQueriesSupported == FALSE))
128                 {
129                     TracyD3D12Panic("Platform does not support profiling of copy queues.", return);
130                 }
131             }
132 
133             static constexpr uint32_t MaxQueries = 64 * 1024;  // Must be even, because queries are (begin, end) pairs
134             m_queryLimit = MaxQueries;
135 
136             D3D12_QUERY_HEAP_DESC heapDesc{};
137             heapDesc.Type = queue->GetDesc().Type == D3D12_COMMAND_LIST_TYPE_COPY ? D3D12_QUERY_HEAP_TYPE_COPY_QUEUE_TIMESTAMP : D3D12_QUERY_HEAP_TYPE_TIMESTAMP;
138             heapDesc.Count = m_queryLimit;
139             heapDesc.NodeMask = 0;  // #TODO: Support multiple adapters.
140 
141             while (FAILED(device->CreateQueryHeap(&heapDesc, IID_PPV_ARGS(&m_queryHeap))))
142             {
143                 m_queryLimit /= 2;
144                 heapDesc.Count = m_queryLimit;
145             }
146 
147             // Create a readback buffer, which will be used as a destination for the query data.
148 
149             D3D12_RESOURCE_DESC readbackBufferDesc{};
150             readbackBufferDesc.Alignment = 0;
151             readbackBufferDesc.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
152             readbackBufferDesc.Width = m_queryLimit * sizeof(uint64_t);
153             readbackBufferDesc.Height = 1;
154             readbackBufferDesc.DepthOrArraySize = 1;
155             readbackBufferDesc.Format = DXGI_FORMAT_UNKNOWN;
156             readbackBufferDesc.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;  // Buffers are always row major.
157             readbackBufferDesc.MipLevels = 1;
158             readbackBufferDesc.SampleDesc.Count = 1;
159             readbackBufferDesc.SampleDesc.Quality = 0;
160             readbackBufferDesc.Flags = D3D12_RESOURCE_FLAG_NONE;
161 
162             D3D12_HEAP_PROPERTIES readbackHeapProps{};
163             readbackHeapProps.Type = D3D12_HEAP_TYPE_READBACK;
164             readbackHeapProps.CPUPageProperty = D3D12_CPU_PAGE_PROPERTY_UNKNOWN;
165             readbackHeapProps.MemoryPoolPreference = D3D12_MEMORY_POOL_UNKNOWN;
166             readbackHeapProps.CreationNodeMask = 0;
167             readbackHeapProps.VisibleNodeMask = 0;  // #TODO: Support multiple adapters.
168 
169             if (FAILED(device->CreateCommittedResource(&readbackHeapProps, D3D12_HEAP_FLAG_NONE, &readbackBufferDesc, D3D12_RESOURCE_STATE_COPY_DEST, nullptr, IID_PPV_ARGS(&m_readbackBuffer))))
170             {
171                 TracyD3D12Panic("Failed to create query readback buffer.", return);
172             }
173 
174             if (FAILED(device->CreateFence(0, D3D12_FENCE_FLAG_NONE, IID_PPV_ARGS(&m_payloadFence))))
175             {
176                 TracyD3D12Panic("Failed to create payload fence.", return);
177             }
178 
179             float period = [queue]()
180             {
181                 uint64_t timestampFrequency;
182                 if (FAILED(queue->GetTimestampFrequency(&timestampFrequency)))
183                 {
184                     return 0.0f;
185                 }
186                 return static_cast<float>( 1E+09 / static_cast<double>(timestampFrequency) );
187             }();
188 
189             if (period == 0.0f)
190             {
191                 TracyD3D12Panic("Failed to get timestamp frequency.", return);
192             }
193 
194             uint64_t cpuTimestamp;
195             uint64_t gpuTimestamp;
196             if (FAILED(queue->GetClockCalibration(&gpuTimestamp, &cpuTimestamp)))
197             {
198                 TracyD3D12Panic("Failed to get queue clock calibration.", return);
199             }
200 
201             // Save the device cpu timestamp, not the profiler's timestamp.
202             m_prevCalibrationTicksCPU = cpuTimestamp;
203 
204             cpuTimestamp = Profiler::GetTime();
205 
206             // all checked: ready to roll
207             m_contextId = GetGpuCtxCounter().fetch_add(1);
208 
209             auto* item = Profiler::QueueSerial();
210             MemWrite(&item->hdr.type, QueueType::GpuNewContext);
211             MemWrite(&item->gpuNewContext.cpuTime, cpuTimestamp);
212             MemWrite(&item->gpuNewContext.gpuTime, gpuTimestamp);
213             MemWrite(&item->gpuNewContext.thread, decltype(item->gpuNewContext.thread)(0)); // #TODO: why 0 instead of GetThreadHandle()?
214             MemWrite(&item->gpuNewContext.period, period);
215             MemWrite(&item->gpuNewContext.context, GetId());
216             MemWrite(&item->gpuNewContext.flags, GpuContextCalibration);
217             MemWrite(&item->gpuNewContext.type, GpuContextType::Direct3D12);
218             SubmitQueueItem(item);
219         }
220 
221         ~D3D12QueueCtx()
222         {
223             ZoneScopedC(Color::Red4);
224             // collect all pending timestamps
225             while (m_payloadFence->GetCompletedValue() != m_activePayload)
226                 /* busy-wait ... */;
227             Collect();
228             m_payloadFence->Release();
229             m_readbackBuffer->Release();
230             m_queryHeap->Release();
231         }
232 
233 
234         void NewFrame()
235         {
236             uint32_t queryCounter = m_queryCounter.exchange(0);
237             m_payloadQueue.emplace(D3D12QueryPayload{ m_previousQueryCounter, queryCounter });
238             m_previousQueryCounter += queryCounter;
239 
240             if (m_previousQueryCounter >= m_queryLimit)
241             {
242                 m_previousQueryCounter -= m_queryLimit;
243             }
244 
245             m_queue->Signal(m_payloadFence, ++m_activePayload);
246         }
247 
248         void Name( const char* name, uint16_t len )
249         {
250             auto ptr = (char*)tracy_malloc( len );
251             memcpy( ptr, name, len );
252 
253             auto item = Profiler::QueueSerial();
254             MemWrite( &item->hdr.type, QueueType::GpuContextName );
255             MemWrite( &item->gpuContextNameFat.context, GetId());
256             MemWrite( &item->gpuContextNameFat.ptr, (uint64_t)ptr );
257             MemWrite( &item->gpuContextNameFat.size, len );
258             SubmitQueueItem(item);
259         }
260 
261         void Collect()
262         {
263             ZoneScopedC(Color::Red4);
264 
265 #ifdef TRACY_ON_DEMAND
266             if (!GetProfiler().IsConnected())
267             {
268                 m_queryCounter = 0;
269 
270                 return;
271             }
272 #endif
273 
274             // Find out what payloads are available.
275             const auto newestReadyPayload = m_payloadFence->GetCompletedValue();
276             const auto payloadCount = m_payloadQueue.size() - (m_activePayload - newestReadyPayload);
277 
278             if (!payloadCount)
279             {
280                 return;  // No payloads are available yet, exit out.
281             }
282 
283             D3D12_RANGE mapRange{ 0, m_queryLimit * sizeof(uint64_t) };
284 
285             // Map the readback buffer so we can fetch the query data from the GPU.
286             void* readbackBufferMapping = nullptr;
287 
288             if (FAILED(m_readbackBuffer->Map(0, &mapRange, &readbackBufferMapping)))
289             {
290                 TracyD3D12Panic("Failed to map readback buffer.", return);
291             }
292 
293             auto* timestampData = static_cast<uint64_t*>(readbackBufferMapping);
294 
295             for (uint32_t i = 0; i < payloadCount; ++i)
296             {
297                 const auto& payload = m_payloadQueue.front();
298 
299                 for (uint32_t j = 0; j < payload.m_queryCount; ++j)
300                 {
301                     const auto counter = (payload.m_queryIdStart + j) % m_queryLimit;
302                     const auto timestamp = timestampData[counter];
303                     const auto queryId = counter;
304 
305                     auto* item = Profiler::QueueSerial();
306                     MemWrite(&item->hdr.type, QueueType::GpuTime);
307                     MemWrite(&item->gpuTime.gpuTime, timestamp);
308                     MemWrite(&item->gpuTime.queryId, static_cast<uint16_t>(queryId));
309                     MemWrite(&item->gpuTime.context, GetId());
310 
311                     Profiler::QueueSerialFinish();
312                 }
313 
314                 m_payloadQueue.pop();
315             }
316 
317             m_readbackBuffer->Unmap(0, nullptr);
318 
319             // Recalibrate to account for drift.
320             RecalibrateClocks();
321         }
322 
323     private:
324         tracy_force_inline uint32_t NextQueryId()
325         {
326             uint32_t queryCounter = m_queryCounter.fetch_add(2);
327             if (queryCounter >= m_queryLimit)
328             {
329                 TracyD3D12Panic("Submitted too many GPU queries! Consider increasing MaxQueries.");
330                 // #TODO: consider returning an invalid id or sentinel value here
331             }
332 
333             const uint32_t id = (m_previousQueryCounter + queryCounter) % m_queryLimit;
334 
335             return id;
336         }
337 
338         tracy_force_inline uint8_t GetId() const
339         {
340             return m_contextId;
341         }
342     };
343 
344     class D3D12ZoneScope
345     {
346         const bool m_active;
347         D3D12QueueCtx* m_ctx = nullptr;
348         ID3D12GraphicsCommandList* m_cmdList = nullptr;
349         uint32_t m_queryId = 0;  // Used for tracking in nested zones.
350 
351         tracy_force_inline void WriteQueueItem(QueueItem* item, QueueType type, uint64_t srcLocation)
352         {
353             MemWrite(&item->hdr.type, type);
354             MemWrite(&item->gpuZoneBegin.cpuTime, Profiler::GetTime());
355             MemWrite(&item->gpuZoneBegin.srcloc, srcLocation);
356             MemWrite(&item->gpuZoneBegin.thread, GetThreadHandle());
357             MemWrite(&item->gpuZoneBegin.queryId, static_cast<uint16_t>(m_queryId));
358             MemWrite(&item->gpuZoneBegin.context, m_ctx->GetId());
359             Profiler::QueueSerialFinish();
360         }
361 
362         tracy_force_inline D3D12ZoneScope(D3D12QueueCtx* ctx, ID3D12GraphicsCommandList* cmdList, bool active)
363 #ifdef TRACY_ON_DEMAND
364             : m_active(active&& GetProfiler().IsConnected())
365 #else
366             : m_active(active)
367 #endif
368         {
369             if (!m_active) return;
370 
371             m_ctx = ctx;
372             m_cmdList = cmdList;
373 
374             m_queryId = m_ctx->NextQueryId();
375             m_cmdList->EndQuery(m_ctx->m_queryHeap, D3D12_QUERY_TYPE_TIMESTAMP, m_queryId);
376         }
377 
378     public:
379         tracy_force_inline D3D12ZoneScope(D3D12QueueCtx* ctx, ID3D12GraphicsCommandList* cmdList, const SourceLocationData* srcLocation, bool active)
380             : D3D12ZoneScope(ctx, cmdList, active)
381         {
382             if (!m_active) return;
383 
384             auto* item = Profiler::QueueSerial();
385             WriteQueueItem(item, QueueType::GpuZoneBeginSerial, reinterpret_cast<uint64_t>(srcLocation));
386         }
387 
388         tracy_force_inline D3D12ZoneScope(D3D12QueueCtx* ctx, ID3D12GraphicsCommandList* cmdList, const SourceLocationData* srcLocation, int depth, bool active)
389             : D3D12ZoneScope(ctx, cmdList, active)
390         {
391             if (!m_active) return;
392 
393             auto* item = Profiler::QueueSerialCallstack(Callstack(depth));
394             WriteQueueItem(item, QueueType::GpuZoneBeginCallstackSerial, reinterpret_cast<uint64_t>(srcLocation));
395         }
396 
397         tracy_force_inline D3D12ZoneScope(D3D12QueueCtx* ctx, uint32_t line, const char* source, size_t sourceSz, const char* function, size_t functionSz, const char* name, size_t nameSz, ID3D12GraphicsCommandList* cmdList, bool active)
398             : D3D12ZoneScope(ctx, cmdList, active)
399         {
400             if (!m_active) return;
401 
402             const auto sourceLocation = Profiler::AllocSourceLocation(line, source, sourceSz, function, functionSz, name, nameSz);
403 
404             auto* item = Profiler::QueueSerial();
405             WriteQueueItem(item, QueueType::GpuZoneBeginAllocSrcLocSerial, sourceLocation);
406         }
407 
408         tracy_force_inline D3D12ZoneScope(D3D12QueueCtx* ctx, uint32_t line, const char* source, size_t sourceSz, const char* function, size_t functionSz, const char* name, size_t nameSz, ID3D12GraphicsCommandList* cmdList, int depth, bool active)
409             : D3D12ZoneScope(ctx, cmdList, active)
410         {
411             if (!m_active) return;
412 
413             const auto sourceLocation = Profiler::AllocSourceLocation(line, source, sourceSz, function, functionSz, name, nameSz);
414 
415             auto* item = Profiler::QueueSerialCallstack(Callstack(depth));
416             WriteQueueItem(item, QueueType::GpuZoneBeginAllocSrcLocCallstackSerial, sourceLocation);
417         }
418 
419         tracy_force_inline ~D3D12ZoneScope()
420         {
421             if (!m_active) return;
422 
423             const auto queryId = m_queryId + 1;  // Our end query slot is immediately after the begin slot.
424             m_cmdList->EndQuery(m_ctx->m_queryHeap, D3D12_QUERY_TYPE_TIMESTAMP, queryId);
425 
426             auto* item = Profiler::QueueSerial();
427             MemWrite(&item->hdr.type, QueueType::GpuZoneEndSerial);
428             MemWrite(&item->gpuZoneEnd.cpuTime, Profiler::GetTime());
429             MemWrite(&item->gpuZoneEnd.thread, GetThreadHandle());
430             MemWrite(&item->gpuZoneEnd.queryId, static_cast<uint16_t>(queryId));
431             MemWrite(&item->gpuZoneEnd.context, m_ctx->GetId());
432             Profiler::QueueSerialFinish();
433 
434             m_cmdList->ResolveQueryData(m_ctx->m_queryHeap, D3D12_QUERY_TYPE_TIMESTAMP, m_queryId, 2, m_ctx->m_readbackBuffer, m_queryId * sizeof(uint64_t));
435         }
436     };
437 
438     static inline D3D12QueueCtx* CreateD3D12Context(ID3D12Device* device, ID3D12CommandQueue* queue)
439     {
440         auto* ctx = static_cast<D3D12QueueCtx*>(tracy_malloc(sizeof(D3D12QueueCtx)));
441         new (ctx) D3D12QueueCtx{ device, queue };
442 
443         return ctx;
444     }
445 
446     static inline void DestroyD3D12Context(D3D12QueueCtx* ctx)
447     {
448         ctx->~D3D12QueueCtx();
449         tracy_free(ctx);
450     }
451 
